#ifdef OS_DETECTION_ENABLE
void keyboard_post_init_user(void) {
  wait_ms(400);

  switch (detected_host_os()) {
    case OS_WINDOWS:
    case OS_LINUX:
      layer_move(_WIN);
      break;

    case OS_MACOS:
    case OS_IOS:
    default:
      layer_move(_MAC);
      break;
  }
}
#endif

